#include <cstdio>
#include <cstring>
#include <iostream>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
using namespace std;

typedef long long ll;

const int Maxn = 20;
const int Maxl = 16;
const string let = "0123456789abcdef";

ll C[Maxn][Maxn];
ll k;
int t, cur[Maxl];
int ans[Maxn];

ll Solve(int n, const int *av, bool fl = false)
{
	static ll dp[1000];
	memset(dp, 0, sizeof(dp));
	if (fl && av[0] <= 0) return 0;
	for (int i = 0; i < Maxl; i++)
		if (av[i] < 0) return 0;
	dp[n - fl] = 1;
	for (int i = 0; i < Maxl; i++)
		for (int j = 0; j <= n; j++)
			for (int x = 1; x <= j && x <= av[i] - (fl && i == 0); x++)
				dp[j - x] += dp[j] * C[j][x];
	return dp[0];
}

int main()
{
	for (int i = 0; i < Maxn; i++) {
		C[i][0] = C[i][i] = 1;
		for (int j = 1; j < i; j++)
			C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
	}

	cin >> k >> t;
	int len = 1;
	fill(cur, cur + Maxl, t);
	ll got;

	while ((got = Solve(len, cur) - Solve(len, cur, true)) < k) {
		k -= got;
		len++;
	}

	for (int i = 0; i < len; i++) {
		ans[i] = (i ? 0 : 1);
		cur[ans[i]]--;
		while ((got = Solve(len - 1 - i, cur)) < k) {
			k -= got;
			cur[ans[i]]++;
			ans[i]++;
			cur[ans[i]]--;
		}
		printf("%c", let[ans[i]]);
	}

	printf("\n");
	return 0;
}

